-- v1.5: consent-aware email campaign drafts and audit trail; sending requires separately configured provider.
CREATE TABLE IF NOT EXISTS public.helio_email_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),exhibition_id uuid NOT NULL, name text NOT NULL,subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','archived')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),FOREIGN KEY(owner_id,exhibition_id) REFERENCES public.exhibitions(owner_id,id));
CREATE TABLE IF NOT EXISTS public.helio_email_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),campaign_id uuid NOT NULL,exhibitor_id uuid NOT NULL,activity text NOT NULL CHECK(activity IN ('prepared','sent_manually','replied','bounced','unsubscribed')),notes text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,campaign_id) REFERENCES public.helio_email_campaigns(owner_id,id),FOREIGN KEY(owner_id,exhibitor_id) REFERENCES public.exhibitors(owner_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['helio_email_campaigns','helio_email_activity'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_select ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_insert ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_update ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_delete ON public.%I',t); EXECUTE format('CREATE POLICY helio_owner_select ON public.%I FOR SELECT TO authenticated USING (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_update ON public.%I FOR UPDATE TO authenticated USING (owner_id=(SELECT auth.uid())) WITH CHECK (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_delete ON public.%I FOR DELETE TO authenticated USING (owner_id=(SELECT auth.uid()))',t); END LOOP; END $$;
NOTIFY pgrst,'reload schema';
